def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    if 'slice' in tt:
        return 'slice'
    return ''

def hook(ctx, nb):
    tt = text(val(ctx, 'task.task_type', ''))
    target = text(val(ctx, 'task.target_type', ''))
    dest = text(val(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(val(ctx, 'world.inventory', ''))
    if target and act.startswith('take ') and target in act and 'pick up' in obs:
        nb['target_taken'] = True
    if verb and target and target in act and act.startswith(verb + ' '):
        nb['transformed'] = True
    pc = val(ctx, 'world.placed_count', nb.get('placed_count', 0))
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if target and act.startswith('put ') and target in act and 'you put' in obs:
        if not verb or nb.get('transformed'):
            old = nb.get('placed_count', 0)
            try:
                old = int(old)
            except Exception:
                old = 0
            pc = max(pc, old + 1)
    nb['placed_count'] = pc
    has_target = bool(target and target in inv)
    has_any = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and 'empty' not in inv)
    wrong = bool(has_any and target and not has_target)
    take_ok = bool(target and any(a.startswith('take ') and target in a for a in ctx.get('admissible', [])))
    put_ok = bool(target and dest and any(a.startswith('put ') and target in a and dest in a for a in ctx.get('admissible', [])))
    if wrong:
        stage = 'wrong_inventory'
    elif has_target:
        if verb and not nb.get('transformed'):
            stage = 'transform'
        elif put_ok:
            stage = 'put_target'
        else:
            stage = 'go_destination'
    elif take_ok or val(ctx, 'world.target_found', False) or val(ctx, 'world.target_location', ''):
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['required_verb'] = verb
    return None

