def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(nb.get('task_type', ''))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target item. Do not put it at the destination; recover by setting it aside if needed, then find and take the requested target type.'
    elif stage == 'take_target' and target:
        msg = 'A requested target type is available here. Take a ' + target + ' instead of continuing to search or examine unrelated objects.'
    elif stage == 'transform' and target and verb:
        msg = 'You have the target. Use the admissible ' + verb + ' action on the ' + target + ' before placing it at the destination.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the ' + target + ' to a ' + dest + ' and use the admissible put action there; avoid extra searching.'
    elif stage == 'put_target' and target and dest:
        msg = 'At the destination with the target. Use the admissible put action for the ' + target + ' in/on the ' + dest + '.'
    elif stage == 'find_target' and target and (val(ctx, 'predicates.same_action_repeated', False) or val(ctx, 'predicates.same_observation_repeated', False) or val(ctx, 'predicates.remaining_steps_low', False)):
        msg = 'Search unopened or unvisited containers for the requested ' + target + '; when its take action appears, take it immediately.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

