def hook(ctx, nb):
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    tt = nb.get('task_type') or text(val(ctx, 'task.task_type', ''))
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    if not target or not act:
        return None
    inv = text(val(ctx, 'world.inventory', ''))
    has_target = bool(target in inv)
    has_any = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and 'empty' not in inv)
    wrong = bool(has_any and not has_target)
    if wrong and dest and act.startswith('put ') and dest in act:
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested target type. Do not place a wrong inventory item at the destination; recover by finding the requested target type first.'}
    pc = nb.get('placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if 'two' in tt and target and act.startswith('take ') and target in act and pc > 0:
        locs = text(val(ctx, 'world.placed_locations', ''))
        if locs and locs not in ('none', '[]') and any(loc in act for loc in locs.split()):
            return {'kind': 'block_and_prompt', 'message': 'Do not take back an already placed target item. Find another target item and use the same destination.'}
    return None
